/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
print('setPath', QUrl.setPath.__doc__)
print('setQuery', QUrl.setQuery.__doc__)
print('setFragment', QUrl.setFragment.__doc__)
print('setHost', QUrl.setHost.__doc__)
print('host', QUrl.host.__doc__)
for raw in ['http://localhost/%3A5','http://localhost/%3A','http://localhost/%C3%A4?x=%31&y=2#%3A10','http://%31.example.com/%31?x=%31#%31','http://example.com/%2f%2F%25%3Afoo9?x=%3a9#%2F3','http://example.com/a%2Fb?x=foo%26bar#%23test9']:
    u=QUrl(raw)
    print('\\nraw',raw,'valid',u.isValid(),'encoded',bytes(u.toEncoded()).decode())
    for p in ['host','path','query','fragment']:
        g=getattr(u,p)
        for mode in [None,QUrl.FullyEncoded,QUrl.FullyDecoded]:
            try:
                print(p,mode,repr(g() if mode is None else g(mode)))
            except Exception as e:
                print(p,mode,type(e).__name__,e)
        if p "'!= '"'host':
            for mode in [None,QUrl.DecodedMode,QUrl.StrictMode,QUrl.TolerantMode]:
                v=g(QUrl.FullyEncoded)
                x=QUrl(u)
                s=getattr(x,'set'+p.title())
                try:
                    s(v) if mode is None else s(v,mode)
                    print('roundtrip',p,mode,bytes(x.toEncoded()).decode())
                except Exception as e:
                    print('roundtrip',p,mode,type(e).__name__,e)
PY"

